t.script:
// ============================================
// PORTAL DOCUMENT STAGING WORKFLOW
// Server-side Session Storage (fixes quota issues)
// ============================================

const TOKEN = '';
const BASE_URL = `/subcontractor/upload/${TOKEN}`;

// STATE: Document staging status
const DocState = {
    EMPTY: 'empty',      // No file selected
    STAGED: 'staged',    // File in server session, not saved to DB
    SUBMITTED: 'submitted' // File saved to database
};

// Cached staged docs (synced from server)
let stagedDocsCache = {};

// ============= DOM HELPERS ============= //
function getDocContainer(element) {
    return element.closest('.doc-row-container');
}

function updateUIState(container, state, filename = null) {
    const statusBadge = container.querySelector('.status-badge');
    const stagedIndicator = container.querySelector('.staged-indicator');
    const validateBtn = container.querySelector('.btn-validate');
    const selectBtn = container.querySelector('.btn-select');
    const labelSpan = container.querySelector('.file-label-text');

    // Reset classes
    if (stagedIndicator) stagedIndicator.classList.add('d-none');
    if (validateBtn) validateBtn.classList.add('d-none');

    switch(state) {
        case DocState.STAGED:
            // Hide initial server status badge (e.g., "Manquant")
            if (statusBadge) statusBadge.classList.add('d-none');

            if (stagedIndicator) {
                stagedIndicator.classList.remove('d-none');
                stagedIndicator.textContent = '📎 En attente';
                stagedIndicator.classList.remove('text-success');
            }
            if (validateBtn) validateBtn.classList.remove('d-none');
            if (labelSpan && filename) labelSpan.textContent = filename;
            if (selectBtn) {
                selectBtn.classList.remove('btn-outline-primary');
                selectBtn.classList.add('btn-warning', 'border-warning');
            }
            break;
        case DocState.SUBMITTED:
            // Hide initial server status badge
            if (statusBadge) statusBadge.classList.add('d-none');

            if (stagedIndicator) {
                stagedIndicator.classList.remove('d-none');
                stagedIndicator.textContent = '✓ Envoyé';
                stagedIndicator.classList.add('text-success');
            }
            if (selectBtn) {
                selectBtn.classList.remove('btn-warning', 'border-warning');
            }
            break;
        case DocState.EMPTY:
        default:
            // Show initial server status badge
            if (statusBadge) statusBadge.classList.remove('d-none');

            if (selectBtn) {
                selectBtn.classList.remove('btn-warning', 'border-warning');
            }
            break;
    }
}

// ============= FILE STAGING (Server-side) ============= //
async function onFileSelect(input) {
    const container = getDocContainer(input);
    const file = input.files[0];
    if (!file) return;

    // Update button label immediately with file name
    const labelText = container.querySelector('.file-label-text');
    if (labelText) {
        labelText.innerHTML = `${file.name.substring(0, 20)}...`;
    }

    handleDocStage(input);
}

async function onDateChange(input) {
    handleDocStage(input);
}

async function handleDocStage(element) {
    const container = getDocContainer(element);
    const fileInput = container.querySelector('input[type="file"]');
    const file = fileInput.files[0];

    // If no file selected yet, do nothing
    if (!file) return;

    const docKey = container.dataset.docKey;

    // KBIS and URSSAF: No date input needed (auto-calculated by server)
    const autoExpireDocs = ['kbis', 'urssaf'];

    // For docs requiring date input, check the date
    // NOTE: We allow file upload even without date - date can be added later
    // This provides better UX than blocking the upload
    if (!autoExpireDocs.includes(docKey)) {
        const expiryDateInput = container.querySelector('.input-expiry-date');
        if (expiryDateInput && !expiryDateInput.value && element === fileInput) {
            // Show non-blocking warning - user can add date after file selection
            console.warn(`Date d'expiration manquante pour ${docKey}. L'utilisateur peut l'ajouter après.`);
            // Don't return - allow upload to proceed
        }
    }

    // Show loading
    const spinner = container.querySelector('.spinner-border');
    if (spinner) spinner.classList.remove('d-none');

    // Upload to server session via FormData
    const formData = new FormData();
    formData.append('doc_key', docKey);
    formData.append('file', file);

    // Only send date for non-auto docs
    if (!autoExpireDocs.includes(docKey)) {
        const expiryDateInput = container.querySelector('.input-expiry-date');
        if (expiryDateInput?.value) {
            formData.append('expiry_date', expiryDateInput.value);
        }
    }

    try {
        const response = await fetch(`${BASE_URL}/stage`, {
            method: 'POST',
            body: formData
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const result = await response.json();

        if (result.success) {
            // Update local cache with expiry returned by server
            stagedDocsCache[docKey] = { 
                filename: result.filename,
                expiry_date: result.expiry_date 
            };

            // Update UI
            updateUIState(container, DocState.STAGED, result.filename);
            updateGlobalSubmitButton();
        } else {
            alert('Erreur: ' + (result.error || 'Échec du staging'));
        }
    } catch (error) {
        console.error('Staging error:', error);
        alert('Erreur de connexion au serveur.');
    } finally {
        if (spinner) spinner.classList.add('d-none');
    }
}

// ============= GLOBAL SUBMIT ============= //
async function submitAllDocuments() {
    const count = Object.keys(stagedDocsCache).length;
    if (count === 0) {
        alert('Aucun document en attente.');
        return;
    }

    // CLIENT-SIDE VALIDATION FOR EXPIRY
    const REQUIRED_EXPIRY_DOCS = ['cni', 'insurance_dec'];
    const DOC_NAMES = {'cni': "Carte d'identité", 'insurance_dec': 'Assurance Décennale'};

    for (const [docKey, docData] of Object.entries(stagedDocsCache)) {
        if (REQUIRED_EXPIRY_DOCS.includes(docKey)) {
            if (!docData.expiry_date) {
                // Try to get from input fallback
                const container = document.querySelector(`[data-doc-key="${docKey}"]`);
                const input = container ? container.querySelector('.input-expiry-date') : null;

                if (!input || !input.value) {
                    alert(`Veuillez renseigner la date d'expiration pour : ${DOC_NAMES[docKey] || docKey}`);
                    // Highlight the missing field
                    if (input) {
                        input.style.border = "2px solid red";
                        input.scrollIntoView({behavior: "smooth", block: "center"});
                    }
                    return; // Stop submission
                } else {
                    // Update cache if found in input but lost in cache (unlikely but safe)
                    stagedDocsCache[docKey].expiry_date = input.value;
                }
            }
        }
    }


    const submitBtn = document.getElementById('global-submit-btn');
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = 'Envoi en cours...';
    }

    try {
        const response = await fetch(`${BASE_URL}/submit-all`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({})
        });
        const result = await response.json();

        if (result.success) {
            // Redirect to success page
            if (result.redirect_url) {
                window.location.href = result.redirect_url;
                return;
            }

            // Fallback (shouldn't reach here normally)
            stagedDocsCache = {};
            updateGlobalSubmitButton();
            alert(`✅ ${result.submitted_count} document(s) envoyé(s) avec succès !`);
        } else {
            alert('Erreur: ' + (result.error || 'Échec de l\'envoi'));
        }
    } catch (error) {
        console.error('Submit all error:', error);
        alert('Erreur de connexion au serveur.');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = 'Soumettre mes documents';
        }
    }
}

// ============= SINGLE DOC SUBMIT (via global) ============= //
async function submitSingleDocument(triggerElement, docKey) {
    // For single doc, just redirect to submit all for simplicity
    // Server will only submit what's in session
    if (!stagedDocsCache[docKey]) {
        alert('Aucun document en attente pour ce type.');
        return;
    }
    await submitAllDocuments();
}

// ============= REQUIRED DOCUMENTS ============= //
// Dynamic calculation based on rendered elements

function updateGlobalSubmitButton() {
    const stagedKeys = Object.keys(stagedDocsCache);
    const btn = document.getElementById('global-submit-btn');
    const badge = document.getElementById('staged-count-badge');

    // Calculate required docs DYNAMICALLY from visible elements
    // Only documents rendered on the page (filtered by controller) are candidates for requirement
    const visibleRequiredDocs = [];
    document.querySelectorAll('.doc-row-container').forEach(container => {
        // If marked required in DOM (dataset.required) and visible
        if (container.dataset.required === 'True') {
            visibleRequiredDocs.push(container.dataset.docKey);
        }
    });

    // Check if ALL visible required documents are staged
    const allRequiredStaged = visibleRequiredDocs.every(k => stagedKeys.includes(k));
    const missingRequired = visibleRequiredDocs.filter(k => !stagedKeys.includes(k));

    if (btn) {
        btn.disabled = !allRequiredStaged;

        // Update button text to show what's missing
        if (missingRequired.length > 0) {
            btn.innerHTML = `Documents requis manquants (${missingRequired.length})`;
            btn.classList.remove('btn-success');
            btn.classList.add('btn-secondary');
        } else {
            btn.innerHTML = `SOUMETTRE ${stagedKeys.length}`;
            btn.classList.remove('btn-secondary');
            btn.classList.add('btn-success');
        }
    }

    // Highlight missing required docs in the UI
    updateMissingDocsIndicators(missingRequired);
}

function updateMissingDocsIndicators(missingKeys) {
    // Add visual indicator to required but missing docs
    document.querySelectorAll('.doc-row-container').forEach(container => {
        const docKey = container.dataset.docKey;
        const isRequired = container.dataset.required === 'True';
        const isMissing = missingKeys.includes(docKey);

        if (isRequired && isMissing) {
            container.classList.add('border-start', 'border-danger', 'border-3');
        } else {
            container.classList.remove('border-start', 'border-danger', 'border-3');
        }
    });
}

// ============= PAGE LOAD: Recover from server session ============= //
document.addEventListener('DOMContentLoaded', async function() {
    try {
        const response = await fetch(`${BASE_URL}/session-state`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({})
        });
        const result = await response.json();

        if (result.success && result.staged_docs) {
            stagedDocsCache = result.staged_docs;

            for (const [docKey, docData] of Object.entries(result.staged_docs)) {
                const container = document.querySelector(`[data-doc-key="${docKey}"]`);
                if (container) {
                    updateUIState(container, DocState.STAGED, docData.filename);
                }
            }
        }
    } catch (error) {
        console.error('Session recovery error:', error);
    }

    updateGlobalSubmitButton();
});
